const fromDate = '2024-01-01';
const toDate = new Date(Date.now() - 46 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
return [{ json: { fromDate, toDate } }];

const { fromDate, toDate } = $input.first().json;

const chunks = [];
let current = new Date(fromDate);
const end = new Date(toDate);

while (current < end) {
  const chunkFrom = current.toISOString().split('T')[0];
  const chunkToTs = new Date(current.getTime() + 30 * 24 * 60 * 60 * 1000 - 1);
  const chunkTo = (chunkToTs > end ? end : chunkToTs).toISOString().split('T')[0];
  chunks.push({ json: { chunkFrom, chunkTo } });
  current = new Date(current.getTime() + 30 * 24 * 60 * 60 * 1000);
}

return chunks;

function tsToIso(val) {
  if (val === null || val === undefined || val === '') return null;
  // If already ISO format (contains T or starts with year), return as-is
  if (typeof val === 'string' && (val.includes('T') || /^\d{4}-/.test(val))) return val;
  const n = parseFloat(val);
  if (isNaN(n)) return null;
  return new Date(n * 1000).toISOString();
}

function feeToCents(val) {
  if (val === null || val === undefined || val === '') return null;
  const n = parseFloat(val);
  if (isNaN(n)) return null;
  return Math.round(n);
}

function parseManualTotalInclVat(charge) {
  // Manual orders only expose charge.charge as a VAT-inclusive euro string.
  // Accept plain amounts only (e.g. "323.40"). Reject rates/text like "119e/h".
  if (!charge || charge.charge === null || charge.charge === undefined || charge.charge === '') {
    return { totalInclVatEur: null, totalInclVatCents: null };
  }
  const raw = String(charge.charge).trim().replace(/\s/g, '').replace(',', '.');
  if (!/^[-+]?\d+(\.\d+)?$/.test(raw)) {
    return { totalInclVatEur: null, totalInclVatCents: null };
  }
  const n = parseFloat(raw);
  if (isNaN(n)) return { totalInclVatEur: null, totalInclVatCents: null };
  return {
    totalInclVatEur: n,
    totalInclVatCents: Math.round(n * 100),
  };
}

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  // Determine if manual order based on presence of manual-order specific fields
  const isManual = d.isManual === true || d.isManual === 'true' || (d.customer !== undefined && d.additionalInfo !== undefined) || (d.orgId !== undefined && d.orgId !== null && d.charge && d.charge.charge !== undefined && d.charge.workPrice === undefined);

  let manualData = null;
  let platformFee = null;
  let serviceFee = null;

  if (isManual) {
    const { totalInclVatEur, totalInclVatCents } = parseManualTotalInclVat(d.charge);
    manualData = {
      customer: d.customer || null,
      additionalInfo: d.additionalInfo || null,
      serviceFeeApplied: d.serviceFeeApplied !== undefined ? d.serviceFeeApplied : null,
      payment_method: (d.charge && d.charge.paymentMethod) ? d.charge.paymentMethod : null,
      total_incl_vat_eur: totalInclVatEur,
      total_incl_vat_cents: totalInclVatCents,
      price_basis: 'gross_incl_vat',
      source_field: 'charge.charge',
      raw_charge_total: (d.charge && d.charge.charge !== undefined) ? String(d.charge.charge) : null,
    };
    // Manual orders have no API fee breakdown — leave fee columns null
    platformFee = null;
    serviceFee = null;
  } else {
    platformFee = feeToCents(d.platformFee);
    serviceFee = feeToCents(d.serviceFee);
  }

  const transformed = {
    order_id: d.orderId,
    is_manual: isManual,
    created_at: tsToIso(d.created || d.createdAt),
    organization_name: d.organizationName || null,
    org_id: d.orgId || null,
    hub_id: d.hubId || null,
    order_state: d.orderState || null,
    order_type: d.orderType || null,
    first_schedule: tsToIso(d.firstSchedule),
    schedule: d.schedule || null,
    content: d.content || null,
    stops: d.stops || null,
    charge: d.charge || null,
    platform_fee: platformFee,
    service_fee: serviceFee,
    route_id: d.routeId || null,
    commission_rate: d.commissionRate !== undefined && d.commissionRate !== null ? parseFloat(d.commissionRate) : null,
    underway_at: tsToIso(d.underwayAt),
    in_transit_at: tsToIso(d.inTransitAt),
    delivered_at: tsToIso(d.deliveredAt),
    review: d.review || null,
    manual_data: manualData,
    synced_at: new Date().toISOString()
  };

  if (transformed.order_id) {
    results.push({ json: transformed });
  }
}

return results;

const results = [];

for (const item of $input.all()) {
  const d = item.json;

  const transformed = {
    route_id: d.routeId,
    date: d.date || null,
    hub_id: d.hubId || null,
    partner: d.partner || null,
    internal_cost: d.internalCost !== undefined && d.internalCost !== null ? Math.round(parseFloat(d.internalCost)) : null,
    order_ids: d.orderIds !== undefined ? d.orderIds : null,
    warehouse_order_ids: d.warehouseOrderIds !== undefined ? d.warehouseOrderIds : null,
    total_sales: d.totalSales !== undefined && d.totalSales !== null ? parseFloat(d.totalSales) : null,
    synced_at: new Date().toISOString()
  };

  if (transformed.route_id) {
    results.push({ json: transformed });
  }
}

return results;
